{
  "name": "矩形类图形组件",
  "name_en": "Rectangle-Type Graphic Component",
  "manufacturer": "Nion",
  "description": "用于 Nion Swift 中的非物理图形组件，表示并编辑矩形类二维标注区域，如矩形或椭圆选区。它主要服务于图像/数据视图中的覆盖绘制、区域选择、拖拽调整、旋转、命中测试以及掩膜对象生成，不直接控制任何实验硬件。",
  "description_en": "A non-physical software graphic component in Nion Swift for representing and editing rectangle-like 2D annotation regions, such as rectangular or elliptical selections. It is used for overlay drawing, region selection, drag adjustment, rotation, hit testing, and mask-item generation in image or data views, and does not directly control laboratory hardware.",
  "tag_hints": [
    "ROI annotation",
    "2D graphics overlay",
    "rectangle selection",
    "ellipse selection",
    "hit testing",
    "interactive drag editing",
    "mask generation"
  ],
  "actions": [
    {
      "action_name": "auto-bounds",
      "description": "获取或设置图形边界框。",
      "description_en": "Get or set the graphic bounding box."
    },
    {
      "action_name": "auto-rotation",
      "description": "获取或设置图形旋转量。",
      "description_en": "Get or set the graphic rotation."
    },
    {
      "action_name": "auto-reset_position",
      "description": "将图形位置重置到默认状态。",
      "description_en": "Reset the graphic position to its default state."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出图形的 MIME 数据字典，用于复制、拖放或序列化交换。",
      "description_en": "Export the graphic as a MIME data dictionary for copy, drag-and-drop, or serialized transfer."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复图形属性。",
      "description_en": "Read and restore graphic properties from a MIME data dictionary."
    },
    {
      "action_name": "auto-center",
      "description": "获取或设置图形中心位置。",
      "description_en": "Get or set the graphic center position."
    },
    {
      "action_name": "auto-center_x",
      "description": "获取或设置图形中心的 X 坐标。",
      "description_en": "Get or set the X coordinate of the graphic center."
    },
    {
      "action_name": "auto-center_y",
      "description": "获取或设置图形中心的 Y 坐标。",
      "description_en": "Get or set the Y coordinate of the graphic center."
    },
    {
      "action_name": "auto-size",
      "description": "获取或设置图形尺寸，并保持中心位置不变。",
      "description_en": "Get or set the graphic size while keeping the center fixed."
    },
    {
      "action_name": "auto-width",
      "description": "获取或设置图形宽度。",
      "description_en": "Get or set the graphic width."
    },
    {
      "action_name": "auto-height",
      "description": "获取或设置图形高度。",
      "description_en": "Get or set the graphic height."
    },
    {
      "action_name": "auto-rotation_deg",
      "description": "获取或设置图形的旋转角度（度）。",
      "description_en": "Get or set the graphic rotation angle in degrees."
    },
    {
      "action_name": "auto-get_attributes",
      "description": "获取图形的属性集合。",
      "description_en": "Get the graphic attribute set."
    },
    {
      "action_name": "auto-get_mask_item",
      "description": "生成或返回与该图形对应的掩膜项。",
      "description_en": "Generate or return the mask item corresponding to this graphic."
    },
    {
      "action_name": "auto-test",
      "description": "对给定点执行命中测试，以判断是否选中图形或其可拖拽部分。",
      "description_en": "Perform hit testing on a given point to determine whether the graphic or one of its draggable parts is selected."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始图形拖拽编辑并记录初始状态。",
      "description_en": "Begin interactive drag editing and capture the initial state."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束图形拖拽编辑并提交结果。",
      "description_en": "End interactive drag editing and finalize the result."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "根据拖拽过程和修饰键调整图形的指定部分。",
      "description_en": "Adjust a specified part of the graphic according to drag motion and modifier keys."
    },
    {
      "action_name": "auto-nudge",
      "description": "按给定增量微调图形位置或几何参数。",
      "description_en": "Nudge the graphic position or geometry by a given delta."
    }
  ]
}

